"""Generate src/orch_dashboard/web/look-icons.js and look.css colours from contracts/look/ (icons, look.json).

Run from anywhere:  python3 workspace-addons/dashboard/tools/gen_look_icons.py [--check]
--check exits 1 when the generated files differ (tests/test_look.py runs it that way).
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
LOOK = ROOT / "contracts" / "look"
WEB = Path(__file__).resolve().parents[1] / "src" / "orch_dashboard" / "web"
OUT = WEB / "look-icons.js"
CSS = WEB / "look-colors.css"


def build() -> tuple[str, str]:
    data = json.loads((ROOT / "contracts" / "look.json").read_text(encoding="utf-8"))
    icons = {}
    for i in data["icons"]:
        svg = (LOOK / "icons" / f"{i['id']}.svg").read_text(encoding="utf-8")
        m = re.fullmatch(r"\s*<svg[^>]*>(.*)</svg>\s*", svg, re.DOTALL)
        if not m or "<script" in svg or re.search(r"\son\w+=", svg):
            raise SystemExit(f"icon {i['id']}: not a plain svg")
        icons[i["id"]] = {
            "l": i["label"],
            "c": i["category"],
            "k": " ".join(i.get("keywords") or []),
            "b": m.group(1).strip(),
        }
    doc = {
        "categories": data["categories"],
        "colors": data["colors"],
        "icons": icons,
    }
    js = (
        "/* Generated by tools/gen_look_icons.py from contracts/look.json and contracts/look/icons (Lucide, ISC). Do not edit. */\n"
        "window.OrchLookData=" + json.dumps(doc, ensure_ascii=False, separators=(",", ":")) + ";\n"
    )
    css = "/* Generated by tools/gen_look_icons.py from contracts/look.json. Do not edit. */\n" + "".join(
        f"[data-c={c['id']}]{{--c:{c['dark']}}}\n.light[data-c={c['id']}]{{--c:{c['light']}}}\n"
        for c in data["colors"]
    )
    return js, css


if __name__ == "__main__":
    js, css = build()
    if "--check" in sys.argv:
        ok = (
            OUT.exists()
            and OUT.read_text(encoding="utf-8") == js
            and CSS.exists()
            and CSS.read_text(encoding="utf-8") == css
        )
        sys.exit(0 if ok else 1)
    OUT.write_text(js, encoding="utf-8")
    CSS.write_text(css, encoding="utf-8")
    print(f"wrote {OUT.name} ({len(js)} bytes), {CSS.name}")
